        (void)(callm(L_b, SY("spawn"), Args{(SV("plant:") + pm_pvp70_catalog::HEAD), SV("plant"), (V(12.0) * pvz::getattr(L_b, SY("tile"))), (V(10.0) * pvz::getattr(L_b, SY("tile")))}));
