V C_PvP70Tests::m_pinned_head(const Args& A) {
    V L_b = A.get(0, SY("b"), nullptr, "pinned_head");
    V L_root = A.get(1, SY("root"), nullptr, "pinned_head");
    V L_col = A.get(2, SY("col"), nullptr, "pinned_head");
    V L_c;
    V L_head;
    V L_original;
    V L_pinned;
    L_c = pvz::getattr(pvz::getattr(L_b, SY("content")), SY("pvp70"));
    L_original = pvz::getattr(L_c, SY("update_heads"));
    L_pinned = V::func([=, this](const Args& A) mutable -> V {
    V L_plant = A.get(0, SY("plant"), nullptr, "pinned");
    V L_heads = A.get(1, SY("heads"), nullptr, "pinned");
    V L_h;
    (void)((L_original).call(Args{L_plant, L_heads}));
    { V it1_ = py::iter_list(L_heads);
    for (size_t i1_ = 0; i1_ < it1_.len(); ++i1_) {
        L_h = it1_.idx(int64_t(i1_)); 
        setm(L_h, &Obj::_pvp_head_point, SV("_pvp_head_point"), V::tuple({(L_col * pvz::getattr(L_b, SY("tile"))), (V(9.45) * pvz::getattr(L_b, SY("tile")))}));
        setm(L_h, &Obj::_pvp_head_clock, SV("_pvp_head_clock"), V(0.0));
        (void)(callm(L_c, SY("anchor_head"), Args{L_h}));
    }}
    return V::none();
});
    pvz::setattr(L_c, SY("update_heads"), L_pinned);
    (void)(m_addCleanup(Args{V::func([=, this](const Args& A) -> V { return callm(pvz::getattr(L_c, SY("__dict__")), SY("pop"), Args{SV("update_heads"), V::none()}); })}));
    L_head = rd(callm(L_c, SY("heads"), Args{L_root}), V(0.0));
    (void)(callm(L_c, SY("update_heads"), Args{L_root, V::list({L_head})}));
    return L_head;
    return V::none();
}

